<?php
$slug=$section==='blog'?'':substr($section,5);$post=null;
if($slug!==''){$post=Launch::ready()?row("SELECT * FROM zentro_posts WHERE slug=? AND status='published'",[$slug]):null;if(!$post)fail('Article not found.',404);}
$title=$post['title']??'SEO guides & business growth insights';$description=$post['description']??'Practical SEO Zentro guides to website audits, local SEO, content and business growth.';
if($post){$ogType='article';if($post['image'])$ogImage=cfg('APP_URL').$post['image'];$structuredData=['@context'=>'https://schema.org','@type'=>'BlogPosting','headline'=>$post['title'],'description'=>$description,'datePublished'=>date(DATE_ATOM,strtotime($post['published_at'])),'dateModified'=>date(DATE_ATOM,strtotime($post['updated_at'])),'author'=>['@type'=>'Organization','name'=>'SEO Zentro','url'=>cfg('APP_URL')],'mainEntityOfPage'=>cfg('APP_URL').'/blog/'.$post['slug']];if(!empty($ogImage))$structuredData['image']=$ogImage;}
require ROOT.'/includes/header.php';require ROOT.'/public/zentro-nav.php';?><main id="main" class="container section-pad <?=$post?'narrow':''?>"><span class="eyebrow">THE SEO ZENTRO JOURNAL</span><h1><?=e($title)?></h1><?php if($post):?><p><?=e($description)?></p><p class="small">SEO Zentro · <?=e(date('F j, Y',strtotime($post['published_at'])))?></p><?php if($post['image']):?><img class="blog-cover" src="<?=url($post['image'])?>" alt="<?=e($post['image_alt'])?>"><?php endif;?><article class="zentro-article"><?php foreach(preg_split('/\R\s*\R/',$post['content']) as $paragraph){if(str_starts_with($paragraph,'## '))echo '<h2>'.e(substr($paragraph,3)).'</h2>';else echo '<p>'.nl2br(e($paragraph)).'</p>';}?></article><a href="<?=url('/blog')?>">← All articles</a><?php else:$posts=Launch::posts();?><p><?=e($description)?></p><div class="grid grid-3"><?php foreach($posts as $p):?><article class="card"><?php if($p['image']):?><img class="blog-cover" loading="lazy" src="<?=url($p['image'])?>" alt="<?=e($p['image_alt'])?>"><?php endif;?><h2><a href="<?=url('/blog/'.$p['slug'])?>"><?=e($p['title'])?></a></h2><p><?=e($p['description'])?></p><a href="<?=url('/blog/'.$p['slug'])?>">Read article →</a></article><?php endforeach;?></div><?php if(!$posts):?><p>Our first guides are on their way. Explore our tools to get started today.</p><a class="button" href="<?=url('/features')?>">Explore SEO tools</a><?php endif;endif;?></main><?php require ROOT.'/includes/footer.php';?>
